def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    top={c for c in range(w) if grid[0][c]==1}; bottom={c for c in range(w) if grid[h-1][c]==1}
    left={r for r in range(h) if grid[r][0]==1}; right={r for r in range(h) if grid[r][w-1]==1}
    rows=top_bottom=set(top & bottom)
    rows |= (left & right)
    cols=set(top & bottom)
    # Actually top-bottom alignments are columns; horizontal opposite-edge alignments are rows.
    cols=set(top & bottom)
    rows=set(left & right)
    # Find 4-connected original 2 components; if intersected by a line, recolor entire component.
    seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=2 or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
          rr,cc=stack.pop(); comp.append((rr,cc))
          for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==2 and (nr,nc) not in seen:
              seen.add((nr,nc)); stack.append((nr,nc))
        if any(rr in rows or cc in cols for rr,cc in comp):
          for rr,cc in comp: out[rr][cc]=1
    for r in rows: out[r]=[1]*w
    for c in cols:
      for r in range(h): out[r][c]=1
    return out
