def transform_first_hit(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # components of the original 2-color objects
    comps=[]; comp_at={}; seen=set()
    for r in range(h):
      for c in range(w):
       if grid[r][c]!=2 or (r,c) in seen: continue
       stack=[(r,c)];seen.add((r,c)); comp=[]
       while stack:
        rr,cc=stack.pop();comp.append((rr,cc))
        for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
         if 0<=nr<h and 0<=nc<w and grid[nr][nc]==2 and (nr,nc) not in seen:
          seen.add((nr,nc));stack.append((nr,nc))
       idx=len(comps);comps.append(comp)
       for p in comp: comp_at[p]=idx
    lines=[]
    for r in range(h):
      if grid[r][0]==1 and grid[r][w-1]==1:
       lines.append(('row',r))
    for c in range(w):
      if grid[0][c]==1 and grid[h-1][c]==1:
       lines.append(('col',c))
    hit=set()
    for typ,k in lines:
      # paint the complete beam, then each endpoint changes only the first object it encounters
      if typ=='row':
       for c in range(w): out[k][c]=1
       scans=[range(1,w-1),range(w-2,0,-1)]
       for scan in scans:
        for c in scan:
         if grid[k][c]==2:
          hit.add(comp_at[(k,c)]);break
      else:
       for r in range(h): out[r][k]=1
       scans=[range(1,h-1),range(h-2,0,-1)]
       for scan in scans:
        for r in scan:
         if grid[r][k]==2:
          hit.add(comp_at[(r,k)]);break
    for idx in hit:
      for r,c in comps[idx]:out[r][c]=1
    return out
